<?php
session_start();if(!isset($_SESSION["admin"])){header("Location: login.php");exit;}require "db.php";
$message="";$edit=null;
if(isset($_POST["add"])){ $s=$conn->prepare("INSERT INTO parking_zones(provider_id,zone_name,location,capacity,available_slots,rate) VALUES(?,?,?,?,?,?)");$provider=1;$s->bind_param("issiid",$provider,$_POST["zone_name"],$_POST["location"],$_POST["capacity"],$_POST["available"],$_POST["rate"]);$s->execute();$message="Zone added successfully."; }
if(isset($_POST["update"])){ $s=$conn->prepare("UPDATE parking_zones SET zone_name=?,location=?,capacity=?,available_slots=?,rate=? WHERE id=?");$s->bind_param("ssiidi",$_POST["zone_name"],$_POST["location"],$_POST["capacity"],$_POST["available"],$_POST["rate"],$_POST["id"]);$s->execute();$message="Zone updated successfully."; }
if(isset($_GET["delete"])){ $id=(int)$_GET["delete"];$conn->query("DELETE FROM parking_zones WHERE id=$id");$message="Zone deleted successfully."; }
if(isset($_GET["edit"])){ $id=(int)$_GET["edit"];$r=$conn->query("SELECT * FROM parking_zones WHERE id=$id");$edit=$r->fetch_assoc(); }
$zones=$conn->query("SELECT * FROM parking_zones ORDER BY id");
?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Parking Zones | KumbhPark</title><link rel="stylesheet" href="../style.css"></head>
<body><div class="dashboard"><div class="dashboard-head"><div><span class="small-title">PARKING MANAGEMENT</span><h1>Parking Zones</h1><p>Add, edit and delete zones.</p></div><a class="secondary-btn" href="dashboard.php">Dashboard</a></div>
<?php if($message): ?><div class="message"><?php echo htmlspecialchars($message); ?></div><?php endif; ?>
<form method="POST" class="panel"><div class="form-grid"><input type="hidden" name="id" value="<?php echo htmlspecialchars($edit["id"]??""); ?>"><div class="form-group"><label>Zone Name</label><input name="zone_name" required value="<?php echo htmlspecialchars($edit["zone_name"]??""); ?>"></div><div class="form-group"><label>Location</label><input name="location" required value="<?php echo htmlspecialchars($edit["location"]??""); ?>"></div><div class="form-group"><label>Capacity</label><input name="capacity" type="number" required value="<?php echo htmlspecialchars($edit["capacity"]??""); ?>"></div><div class="form-group"><label>Available Slots</label><input name="available" type="number" required value="<?php echo htmlspecialchars($edit["available_slots"]??""); ?>"></div><div class="form-group"><label>Rate</label><input name="rate" type="number" step="0.01" required value="<?php echo htmlspecialchars($edit["rate"]??""); ?>"></div></div><button class="form-submit" name="<?php echo $edit?"update":"add"; ?>"><?php echo $edit?"Save Changes":"Add Parking Zone"; ?></button></form>
<section class="panel"><table class="data-table"><tr><th>Zone</th><th>Location</th><th>Capacity</th><th>Available</th><th>Rate</th><th>Actions</th></tr><?php while($z=$zones->fetch_assoc()): ?><tr><td><?php echo htmlspecialchars($z["zone_name"]); ?></td><td><?php echo htmlspecialchars($z["location"]); ?></td><td><?php echo $z["capacity"]; ?></td><td><?php echo $z["available_slots"]; ?></td><td>₹<?php echo $z["rate"]; ?></td><td><a class="mini-btn" href="?edit=<?php echo $z["id"]; ?>">Edit</a> <a class="mini-btn danger" href="?delete=<?php echo $z["id"]; ?>" onclick="return confirm('Delete this zone?')">Delete</a></td></tr><?php endwhile; ?></table></section></div></body></html>